from module_adapters._graph_extended_support import Diagram,validate
SOURCE='simgnn-modules/src/layers.py';KEY='simgnn_readout'
LINKS=[('embedding','context.mm','X','tensor'),('weight','context.mm','W','parameter_operand'),('embedding','score.mm','X','retained_value'),('context.view','score.mm','context','tensor'),('embedding','transpose','X','retained_value'),('transpose','readout','X_transpose','tensor'),('score.sigmoid','readout','node_weights','tensor'),('readout','output','in','tensor')]
REQUIRED={'context.mean':dict(dim=0,expression='torch.mean(torch.matmul(embedding, self.weight_matrix), dim=0)'),'context.tanh':dict(kind='tanh'),'score.sigmoid':dict(kind='sigmoid',normalization='independent node gates; no Softmax'),'weight':dict(parameter='weight_matrix',shape='[8,8]'),'readout':dict(expression='torch.mm(torch.t(embedding), sigmoid_scores)',ordered_operands=['embedding.T','sigmoid_scores'],shape='[8,1]')}
CONTRACTS=[('AttentionModule.setup_weights','torch.nn.Parameter(torch.Tensor(self.args.filters_3, self.args.filters_3))'),('AttentionModule.forward','torch.mean(torch.matmul(embedding, self.weight_matrix), dim=0)'),('AttentionModule.forward','torch.tanh(global_context)'),('AttentionModule.forward','torch.sigmoid(torch.mm(embedding, transformed_global.view(-1, 1)))'),('AttentionModule.forward','torch.mm(torch.t(embedding), sigmoid_scores)')]
def build():
 d=Diagram(KEY,'SimGNN graph attention readout',SOURCE,'AttentionModule.forward','One AttentionModule on node embeddings; excludes graph convolutions, histogram, tensor similarity network and task head.',dict(filters_3=8,node_count='N',global_reduction='mean nodes',attention_normalizer='sigmoid, not Softmax',weighted_readout='sum, not normalized mean',output_orientation='[8,1]'))
 params=d.ref('AttentionModule.setup_weights');d.input('embedding','Retained node embeddings X','[N,8]');d.input('weight','Owned context weight W','[8,8]',kind='parameter',source=params,parameter='weight_matrix')
 d.stage('context','Mean projected global context','[8,1]',0,[('mm','Node embeddings @ W','matmul','[N,8]',dict(expression='torch.matmul(embedding, self.weight_matrix)')),('mean','Mean over nodes / dim0','mean','[8]',REQUIRED['context.mean']),('tanh','Tanh global context','tanh','[8]',dict()),('view','View column context','tensor','[8,1]',dict())],suppress_input_boundary=True)
 d.stage('score','Independent per-node gates','[N,1]',1,[('mm','SAME X @ context','matmul','[N,1]',dict()),('sigmoid','Sigmoid / NOT Softmax','sigmoid','[N,1]',{k:v for k,v in REQUIRED['score.sigmoid'].items() if k!='kind'})],suppress_input_boundary=True)
 d.node('transpose','Transpose SAME node embeddings','tensor','[8,N]',1,expression='torch.t(embedding)');d.node('readout','X.T @ sigmoid node weights','matmul','[8,1]',2,**{k:v for k,v in REQUIRED['readout'].items() if k!='shape'})
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if r=='retained_value' else 'out',ds='left' if r=='retained_value' else 'in')
 return d.build(d.entry,'[8,1]','SimGNNReadout.md',['One W[8,8] creates a mean projected global context, then Tanh. The ORIGINAL node embeddings independently compute sigmoid gates against this context.','Final representation is X.T @ sigmoid_scores, a weighted SUM. Sigmoid gates neither sum to one nor become Softmax attention.','The SAME original embedding appears in context projection, node scoring and final readout; the output is a column [8,1].'],['Do not substitute graph GAT incoming edge Softmax, dot-product sequence attention or normalize the weighted readout.'])
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(attention_normalizer='sigmoid, not Softmax',weighted_readout='sum, not normalized mean'))
